command:
const me = canvas.tokens.controlled?.at(0)?.document;
if (!me) {
  ui.notifications.error("You need to select yourself to use this macro.")
  return;
}

canvas.tokens.setTargets(game.scenes.active.tokens.filter(t=>t !== me && t.disposition == me.disposition).map(t=>t.object?.id), { mode: "replace" });
